use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let text = input["text"].as_str().unwrap();
    let pattern = input["pattern"].as_str().unwrap();
    let mut result = Vec::new();
    let mut start = 0;
    let mut pos = 0;
    while let Some(c) = text.chars().nth(pos) {
        if c == pattern[pos] {
            start += 1;
            pos += 1;
            if pos == pattern.len() {
                result.push(start);
                start = pos;
            }
        } else {
            pos += 1;
        }
    }
    Value::Array(result)
}
